using System;using System.Collections.Generic;using System.ComponentModel;using System.Linq;using System.Runtime.InteropServices;using System.Text;
namespace Ada {
 internal static class BluetoothProperties {
  [StructLayout(LayoutKind.Sequential)]struct DeviceInfo{public uint Size;public Guid ClassGuid;public uint DevInst;public IntPtr Reserved;}
