  [DllImport("setupapi.dll",SetLastError=true)]static extern bool SetupDiGetDevicePropertyW(IntPtr set,ref DeviceInfo info,ref PropertyKey key,out uint type,byte[] data,uint size,out uint needed,uint flags);
