  static readonly PropertyKey Name=new PropertyKey("A45C254E-DF1C-4EFD-8020-67D146A850E0",14),Description=new PropertyKey("A45C254E-DF1C-4EFD-8020-67D146A850E0",2),Container=new PropertyKey("8C7ED206-3F8A-4827-B3AB-AE9E1FAEFC6C",2),Connected=new PropertyKey("83DA6326-97A6-4088-9453-A1923F573B29",15);
