  static readonly PropertyKey Battery=new PropertyKey("104EA319-6EE2-4701-BD47-8DDBF425BBE5",2);
  static object Read(IntPtr set,ref DeviceInfo info,PropertyKey key){var buffer=new byte[2048];uint type,needed;if(!SetupDiGetDevicePropertyW(set,ref info,ref key,out type,buffer,(uint)buffer.Length,out needed,0))return null;if(type==3&&needed>=1)return (int)buffer[0];if(type==7&&needed>=4)return BitConverter.ToUInt32(buffer,0);if(type==0x11&&needed>=1)return buffer[0]!=0;if(type==0x12&&needed>=2)return Encoding.Unicode.GetString(buffer,0,(int)needed).TrimEnd('\0');if(type==0xd&&needed>=16){var bytes=new byte[16];Array.Copy(buffer,bytes,16);return new Guid(bytes).ToString();}return null;}
  internal static List<BluetoothBattery> Read(){var set=SetupDiGetClassDevsW(IntPtr.Zero,null,IntPtr.Zero,6);if(set==new IntPtr(-1))throw new Win32Exception();try{var rows=new List<BluetoothBattery>();for(uint index=0;index<10000;index++){var info=new DeviceInfo{Size=(uint)Marshal.SizeOf(typeof(DeviceInfo))};if(!SetupDiEnumDeviceInfo(set,index,ref info)){if(Marshal.GetLastWin32Error()==259)break;throw new Win32Exception();}var id=new StringBuilder(1024);uint needed;if(!SetupDiGetDeviceInstanceIdW(set,ref info,id,(uint)id.Capacity,out needed))continue;string instance=id.ToString();if(!instance.StartsWith("BTHENUM",StringComparison.OrdinalIgnoreCase)&&!instance.StartsWith("BTHLE",StringComparison.OrdinalIgnoreCase))continue;var battery=Read(set,ref info,Battery);int? level=null;if(battery!=null){int n=Convert.ToInt32(battery);if(n>=0&&n<=100)level=n;}bool connected=Object.Equals(Read(set,ref info,Connected),true);if(!connected&&!level.HasValue)continue;string name=Convert.ToString(Read(set,ref info,Name)??Read(set,ref info,Description));if(String.IsNullOrWhiteSpace(name))continue;rows.Add(new BluetoothBattery{Id=instance,Container=Convert.ToString(Read(set,ref info,Container)),Name=name,Connected=connected,Percent=level});}
   var result=new List<BluetoothBattery>();foreach(var group in rows.GroupBy(d=>String.IsNullOrEmpty(d.Container)?d.Id:d.Container)){if(!group.Any(d=>d.Connected))continue;var root=group.OrderByDescending(d=>d.Connected).ThenBy(d=>d.Name.Length).First();var battery=group.FirstOrDefault(d=>d.Percent.HasValue);result.Add(new BluetoothBattery{Id=root.Id,Container=root.Container,Name=root.Name,Connected=true,Percent=battery==null?null:battery.Percent});}return result.OrderBy(d=>d.Name).ToList();
  }finally{SetupDiDestroyDeviceInfoList(set);}}
 }
